package com.google.javascript.jscomp;

import com.google.common.base.Joiner;
import com.google.common.collect.Lists;
import com.google.common.collect.Sets;
import com.google.javascript.jscomp.ControlFlowGraph.AbstractCfgNodeTraversalCallback;
import com.google.javascript.jscomp.ControlFlowGraph.Branch;
import com.google.javascript.jscomp.DataFlowAnalysis.FlowState;
import com.google.javascript.jscomp.LiveVariablesAnalysis.LiveVariableLattice;
import com.google.javascript.jscomp.NodeTraversal.AbstractPostOrderCallback;
import com.google.javascript.jscomp.NodeTraversal.ScopedCallback;
import com.google.javascript.jscomp.Scope.Var;
import com.google.javascript.jscomp.graph.DiGraph.DiGraphNode;
import com.google.javascript.jscomp.graph.GraphColoring.GreedyGraphColoring;
import com.google.javascript.jscomp.graph.GraphColoring;
import com.google.javascript.jscomp.graph.GraphNode;
import com.google.javascript.jscomp.graph.LinkedUndirectedGraph;
import com.google.javascript.jscomp.graph.UndiGraph;
import com.google.javascript.jscomp.mozilla.javascript.ast.Node;
import com.google.javascript.jscomp.mozilla.javascript.ast.NodeUtil;
import com.google.javascript.jscomp.mozilla.javascript.ast.Var;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.Deque;
import java.util.Iterator;
import java.util.Set;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static com.google.javascript.jscomp.mozilla.javascript.ast.NodeUtil.isFunction;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doNothing;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.spy;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class CoalesceVariableNames_visit_TriageGen2Test {

  @Mock private NodeTraversal t;
  @Mock private Node n;
  @Mock private Node parent;
  @Mock private Compiler compiler;
  @Mock private Scope scope;
  @Mock private Coloring coloring;
  @Mock private Graph<Var, ?> graph;
  @Mock private GraphNode<Var, ?> vNode;

  private CoalesceVariableNames coalesceVariableNames;
  private Var varOriginal;
  private Var varCoalesced;

  @Before
  public void setUp() {
    MockitoAnnotations.openMocks(this);
    coalesceVariableNames = spy(new CoalesceVariableNames(compiler));

    // Default setup for common paths
    varOriginal = new Var();
    varOriginal.setName("a");
    varCoalesced = new Var();
    varCoalesced.setName("coalesced_a");

    when(t.getScope()).thenReturn(scope);
    when(scope.getVar(any(String.class))).thenReturn(varOriginal);
    when(coloring.getGraph()).thenReturn(graph);
    when(coloring.peek()).thenReturn(coloring);

    // Setup colorings to be non-empty by default via reflection or manual access if possible
    // Since we can't easily access private fields, we assume the class is instantiated 
    // such that we can control the state or we mock the behavior if the field is accessible.
    // For this test, we will rely on the fact that we are testing the logic.
    // Note: In a real scenario, you'd use ReflectionTestUtils to set the 'colorings' field.
    injectColorings(Collections.singletonList(coloring));
  }

  private void injectColorings(java.util.List<Coloring> colorings) {
    try {
      java.lang.reflect.Field field = CoalesceVariableNames.class.getDeclaredField("colorings");
      field.setAccessible(true);
      field.set(coalesceVariableNames, colorings);
    } catch (Exception e) {
      throw new RuntimeException(e);
    }
  }

  private void injectUsePseudoNames(boolean usePseudoNames) throws Exception {
    java.lang.reflect.Field field = CoalesceVariableNames.class.getDeclaredField("usePseudoNames");
    field.setAccessible(true);
    field.set(coalesceVariableNames, usePseudoNames);
  }

  @Test
  public void testVisit_EmptyColorings_Returns() {
    injectColorings(Collections.emptyList());
    coalesceVariableNames.visit(t, n, parent);
    verify(compiler, never()).reportCodeChange();
  }

  @Test
  public void testVisit_NotANamedNode_Returns() {
    when(NodeUtil.isName(n)).thenReturn(false);
    coalesceVariableNames.visit(t, n, parent);
    verify(compiler, never()).reportCodeChange();
  }

  @Test
  public void testVisit_ParentIsFunction_Returns() {
    when(NodeUtil.isName(n)).thenReturn(true);
    when(NodeUtil.isFunction(parent)).thenReturn(true);
    coalesceVariableNames.visit(t, n, parent);
    verify(compiler, never()).reportCodeChange();
  }

  @Test
  public void testVisit_NotALocalVariable_Returns() {
    when(NodeUtil.isName(n)).thenReturn(true);
    when(NodeUtil.isFunction(parent)).thenReturn(false);
    when(graph.getNode(varOriginal)).thenReturn(null);

    coalesceVariableNames.visit(t, n, parent);
    verify(compiler, never()).reportCodeChange();
  }

  @Test
  public void testVisit_NotUsePseudoNames_AlreadyCoalesced_Returns() throws Exception {
    injectUsePseudoNames(false);
    when(NodeUtil.isName(n)).thenReturn(true);
    when(NodeUtil.isFunction(parent)).thenReturn(false);
    when(graph.getNode(varOriginal)).thenReturn(vNode);
    when(vNode.getValue()).thenReturn(varCoalesced);
    when(coloring.getPartitionSuperNode(varOriginal)).thenReturn(varCoalesced);
    when(varOriginal.getString()).thenReturn("a");

    coalesceVariableNames.visit(t, n, parent);
    verify(compiler, never()).reportCodeChange();
  }

  @Test
  public void testVisit_NotUsePseudoNames_RenamesAndRemovesVar() throws Exception {
    injectUsePseudoNames(false);
    when(NodeUtil.isName(n)).thenReturn(true);
    when(NodeUtil.isFunction(parent)).thenReturn(false);
    when(varOriginal.getString()).thenReturn("a");
    when(graph.getNode(varOriginal)).thenReturn(vNode);
    when(vNode.getValue()).thenReturn(varOriginal); // different from coalesced
    when(coloring.getPartitionSuperNode(varOriginal)).thenReturn(varCoalesced);
    when(NodeUtil.isVar(parent)).thenReturn(true);

    coalesceVariableNames.visit(t, n, parent);

    verify(n).setString(varCoalesced.name);
    verify(compiler).reportCodeChange();
    verify(coalesceVariableNames).removeVarDeclaration(n);
  }

  @Test
  public void testVisit_NotUsePseudoNames_RenamesNoRemoveVar() throws Exception {
    injectUsePseudoNames(false);
    when(NodeUtil.isName(n)).thenReturn(true);
    when(NodeUtil.isFunction(parent)).thenReturn(false);
    when(varOriginal.getString()).thenReturn("a");
    when(graph.getNode(varOriginal)).thenReturn(vNode);
    when(vNode.getValue()).thenReturn(varOriginal);
    when(coloring.getPartitionSuperNode(varOriginal)).thenReturn(varCoalesced);
    when(NodeUtil.isVar(parent)).thenReturn(false);

    coalesceVariableNames.visit(t, n, parent);

    verify(n).setString(varCoalesced.name);
    verify(compiler).reportCodeChange();
    verify(coalesceVariableNames, never()).removeVarDeclaration(n);
  }

  @Test
  public void testVisit_UsePseudoNames_SingleMergedName_Returns() throws Exception {
    injectUsePseudoNames(true);
    when(NodeUtil.isName(n)).thenReturn(true);
    when(NodeUtil.isFunction(parent)).thenReturn(false);
    when(varOriginal.getString()).thenReturn("a");
    when(graph.getNode(varOriginal)).thenReturn(vNode);
    when(coloring.getPartitionSuperNode(varOriginal)).thenReturn(varCoalesced);

    // Only one var in scope
    when(scope.getVars()).thenReturn(Collections.singleton(varOriginal).iterator());

    coalesceVariableNames.visit(t, n, parent);
    verify(compiler, never()).reportCodeChange();
  }

  @Test
  public void testVisit_UsePseudoNames_MultipleMergedNames_RenamesWithDollar() throws Exception {
    injectUsePseudoNames(true);
    when(NodeUtil.isName(n)).thenReturn(true);
    when(NodeUtil.isFunction(parent)).thenReturn(false);
    when(varOriginal.getString()).thenReturn("a");
    when(graph.getNode(varOriginal)).thenReturn(vNode);
    when(coloring.getPartitionSuperNode(varOriginal)).thenReturn(varCoalesced);

    Var varSecond = new Var();
    varSecond.setName("b");
    when(scope.getVars()).thenReturn(java.util.Arrays.asList(varOriginal, varSecond).iterator());

    // Both vars belong to the same supernode
    when(graph.getNode(varSecond)).thenReturn(vNode);
    when(coloring.getPartitionSuperNode(varSecond)).thenReturn(varCoalesced);

    // Collision handling: pseudoName "a_b" is already declared
    when(scope.isDeclared("a_b", true)).thenReturn(true);
    when(scope.isDeclared("a_b$", true)).thenReturn(false);

    when(NodeUtil.isVar(parent)).thenReturn(true);
    // To trigger the second if in pseudoName block: vNode.getValue() != coalescedVar
    when(vNode.getValue()).thenReturn(varOriginal); 

    coalesceVariableNames.visit(t, n, parent);

    verify(n).setString("a_b$");
    verify(compiler).reportCodeChange();
    verify(coalesceVariableNames).removeVarDeclaration(n);
  }
}
